mapper.select:
select 
  from pep_metering.quota_account
 where id = #{id}

select id, policy_key, revision, mode, limit_units, duration_seconds, effective_at, expires_at
  from pep_metering.quota_policy_version
 where policy_key = #{policyKey} and revision = #{revision}

mapper.update:
update pep_metering.quota_account
   set current_bucket_id = #{bucketId}, version = version + 1, updated_at = now()
 where id = #{accountId} and version = #{expectedVersion}

update pep_metering.quota_bucket
   set limit_units = #{limitUnits}, policy_revision = #{policyRevision}
 where id = #{bucketId}

update pep_metering.quota_bucket
   set held_units = greatest(0, held_units - #{releasedHeld}),
       used_units = used_units + #{settledUnits}
 where id = #{bucketId}

mapper.select:
select id, model_call_id, reserved_units, state
  from pep_metering.quota_reservation
 where model_call_id = #{modelCallId}

select 
  from pep_metering.model_call
 where logical_call_id = #{logicalCallId} and attempt_no = #{attemptNo}

select 
  from pep_metering.model_call
 where id = #{id}

mapper.update:
update pep_metering.quota_reservation
   set state = #{state}, version = version + 1, updated_at = now()
 where id = #{id}

update pep_metering.reservation_charge
   set state = #{state}, settled_units = #{settledUnits}
 where id = #{id}

update pep_metering.quota_account
   set state = 'DEBT', debt_units = greatest(debt_units, #{debtUnits}), updated_at = now()
 where id = #{accountId}

update pep_metering.quota_account
   set state = #{state}, updated_at = now(), version = version + 1
 where id = #{accountId}

mapper.select:
select id, model_call_id, reserved_units, state
  from pep_metering.quota_reservation
 where state = 'DISPATCHED' and created_at < #{cutoff}
 order by created_at
 limit #{limit}
   for update skip locked

select coalesce(max(adjustment_no), 0) + 1
  from pep_metering.usage_adjustment
 where model_call_id = #{modelCallId}

mapper.update:
update pep_metering.quota_bucket
   set used_units = greatest(0, used_units + #{delta})
 where id = #{bucketId}

mapper.select:
select c.id as call_id, c.logical_call_id, c.attempt_no, c.model_profile_key as model, c.provider,
       c.project_id, c.run_id, c.state, c.created_at,
       u.input_tokens, u.output_tokens, u.quota_units, u.quality
  from pep_metering.model_call c
  left join pep_metering.model_usage u on u.model_call_id = c.id
 where c.scope_kind = #{scopeKind} and c.billing_subject_id = #{subjectId}

   and c.model_profile_key = #{modelKey}


   and c.project_id = #{projectId}

 order by c.created_at desc, c.id desc
 limit #{limit}

select coalesce(max(revision), 0)::int
  from pep_metering.quota_policy_version
 where policy_key = #{policyKey}

mapper.update:
update pep_metering.quota_account
   set active_revision = #{revision}, updated_at = now(), version = version + 1
 where id = #{accountId}

mapper.select:
select account_id, new_revision, action, effective_mode, reason
  from pep_metering.quota_change_request
 where actor_id = #{actorId} and idempotency_key = #{idempotencyKey}
